def xep_cau_hoi_vao_kieu(cau_hoi):
    # Kiểm tra xem câu hỏi có phải là câu hỏi về số hay không
    if cau_hoi.lower().endswith(('?', 'ko', 'không', 'muốn', 'tại sao')):
        return 'Câu hỏi về số'
    # Kiểm tra xem câu hỏi có phải là câu hỏi về sự kiện hay không
    elif cau_hoi.lower().endswith(('khi', 'vào lúc', 'tại sao')):
        return 'Câu hỏi về sự kiện'
    # Kiểm tra xem câu hỏi có phải là câu hỏi về địa điểm hay không
    elif cau_hoi.lower().endswith(('ở đâu', 'tại sao ở đây', 'tại sao ở đó')):
        return 'Câu hỏi về địa điểm'
    # Nếu không thuộc bất kỳ loại câu hỏi nào trên, trả về 'Câu hỏi khác'
    else:
        return 'Câu hỏi khác'

